    #[test]
    fn scrub_removes_windows_paths() {
        let input = r"Error at C:\Users\dev\project\main.rs";
        let scrubbed = scrub_for_telemetry(input, &HashMap::new());
        assert!(scrubbed.contains("[PATH]"));
        assert!(!scrubbed.contains(r"C:\Users"));
    }

    #[test]
    fn scrub_removes_slack_xoxb_tokens() {
        let input = "token: xoxb-123456789-abcdefghij";
        let scrubbed = scrub_for_telemetry(input, &HashMap::new());
        assert!(scrubbed.contains("[REDACTED]"));
        assert!(!scrubbed.contains("xoxb-"));
    }

    #[test]
    fn scrub_removes_slack_xoxp_tokens() {
        let input = "token: xoxp-999888777-abcdefghij";
        let scrubbed = scrub_for_telemetry(input, &HashMap::new());
        assert!(scrubbed.contains("[REDACTED]"));
        assert!(!scrubbed.contains("xoxp-"));
    }

    #[test]
    fn scrub_handles_multiple_secret_types_simultaneously() {
        let mut env = HashMap::new();
        env.insert("TOKEN".to_string(), "my-secret-token".to_string());

        let input = "Error at /Users/dev/project with ghp_abcdefghijklmnopqrstuvwxyz1234567890 and my-secret-token";
        let scrubbed = scrub_for_telemetry(input, &env);
        assert!(!scrubbed.contains("/Users/dev"));
        assert!(!scrubbed.contains("ghp_"));
        assert!(!scrubbed.contains("my-secret-token"));
        assert!(scrubbed.contains("[PATH]"));
        assert!(scrubbed.contains("[REDACTED]"));
    }

    #[test]
    fn scrub_handles_empty_input() {
        let scrubbed = scrub_for_telemetry("", &HashMap::new());
        assert_eq!(scrubbed, "");
    }

    #[test]
    fn scrub_ignores_empty_env_values() {
        let mut env = HashMap::new();
        env.insert("API_KEY".to_string(), "".to_string());

        let input = "some normal error text";
        let scrubbed = scrub_for_telemetry(input, &env);
        assert_eq!(scrubbed, input);
    }

    #[test]
    fn consent_display_send() {
        assert_eq!(TelemetryConsent::Send.to_string(), "send");
    }

    #[test]
    fn consent_display_no_thanks() {
        assert_eq!(TelemetryConsent::NoThanks.to_string(), "no_thanks");
    }

    #[test]
    fn consent_display_always() {
        assert_eq!(TelemetryConsent::Always.to_string(), "always");
    }

    #[test]
    fn consent_display_never() {
        assert_eq!(TelemetryConsent::Never.to_string(), "never");
    }

    #[test]
    fn consent_equality() {
        assert_eq!(TelemetryConsent::Send, TelemetryConsent::Send);
        assert_ne!(TelemetryConsent::Send, TelemetryConsent::NoThanks);
        assert_ne!(TelemetryConsent::Always, TelemetryConsent::Never);
    }

    #[test]
    fn reports_dir_ends_with_failure_reports() {
        let dir = reports_dir();
        assert!(dir.ends_with("failure-reports"));
        assert!(dir.to_string_lossy().contains(".bivvy"));
    }

    #[test]
    fn build_report_with_no_exit_code() {
        let report = build_report("npm", "npm install", None, "error", "retry", &HashMap::new());
        assert_eq!(report.exit_code, None);
    }

    #[test]
    fn build_report_scrubs_command_with_secrets() {
        let mut env = HashMap::new();
        env.insert("API_KEY".to_string(), "secret123value".to_string());

        let report = build_report(
            "deploy",
            "curl -H 'Authorization: secret123value'",
            Some(1),
            "",
            "retry",
            &env,
        );
        assert!(!report.command_scrubbed.contains("secret123value"));
    }

    #[test]
    fn failure_report_round_trip_serialization() {
        let report = build_report(
            "cargo",
            "cargo build",
            Some(101),
            "compile error",
            "shell → retry",
            &HashMap::new(),
        );

        let yaml = serde_yaml::to_string(&report).unwrap();
        let deserialized: FailureReport = serde_yaml::from_str(&yaml).unwrap();

        assert_eq!(deserialized.step_name, report.step_name);
        assert_eq!(deserialized.command_scrubbed, report.command_scrubbed);
        assert_eq!(deserialized.exit_code, report.exit_code);
        assert_eq!(deserialized.error_scrubbed, report.error_scrubbed);
        assert_eq!(deserialized.recovery_action, report.recovery_action);
        assert_eq!(deserialized.bivvy_version, report.bivvy_version);
        assert_eq!(deserialized.platform, report.platform);
    }

    #[test]
    fn save_report_creates_nested_directories() {
        let temp = tempfile::TempDir::new().unwrap();
        let nested = temp.path().join("a").join("b").join("c");
        let report = build_report("test", "echo", Some(0), "", "retry", &HashMap::new());

        let path = save_report_to(&report, &nested).unwrap();
        assert!(path.exists());
        assert!(nested.exists());
    }

    #[test]
    fn save_report_filename_contains_step_name() {
        let temp = tempfile::TempDir::new().unwrap();
        let report =
            build_report("bundler", "bundle install", Some(1), "error", "retry", &HashMap::new());

        let path = save_report_to(&report, temp.path()).unwrap();
        let filename = path.file_name().unwrap().to_string_lossy();
        assert!(
            filename.ends_with("-bundler.yml"),
            "Expected step name in filename: {}",
            filename
        );
    }

    #[test]
    fn saved_report_can_be_deserialized() {
        let temp = tempfile::TempDir::new().unwrap();
        let report = build_report(
            "npm",
            "npm install",
            Some(1),
            "ERESOLVE could not resolve",
            "shell → retry",
            &HashMap::new(),
        );

        let path = save_report_to(&report, temp.path()).unwrap();
        let content = std::fs::read_to_string(&path).unwrap();
        let loaded: FailureReport = serde_yaml::from_str(&content).unwrap();

        assert_eq!(loaded.step_name, "npm");
        assert_eq!(loaded.command_scrubbed, "npm install");
        assert_eq!(loaded.exit_code, Some(1));
        assert_eq!(loaded.recovery_action, "shell → retry");
    }

    #[test]
    fn save_multiple_reports_same_step_preserves_all() {
        let temp = tempfile::TempDir::new().unwrap();

        // Save multiple reports with the same step name in rapid succession.
        // These may land within the same second, so the filename must
        // disambiguate to avoid overwriting.
        let mut paths = Vec::new();
        for i in 0..5 {
            let report = build_report(
                "bundler",
                "bundle install",
                Some(i),
                &format!("error {}", i),
                "retry",
                &HashMap::new(),
            );
            paths.push(save_report_to(&report, temp.path()).unwrap());
        }

        // All 5 must be distinct files
        let files: Vec<_> = std::fs::read_dir(temp.path())
            .unwrap()
            .filter_map(|e| e.ok())
            .collect();
        assert_eq!(
            files.len(),
            5,
            "Expected 5 report files, found {}",
            files.len()
        );
    }

    #[test]
    fn prompt_telemetry_shows_report_details() {
        let report = build_report(
            "cargo",
            "cargo build",
            Some(1),
            "compile error",
            "retry",
            &HashMap::new(),
        );
        let mut ui = crate::ui::MockUI::new();
        ui.set_interactive(true);
        ui.set_prompt_response("telemetry_failure", "no_thanks");

        let _ = prompt_telemetry(&mut ui, &report, None).unwrap();

        assert!(ui.has_message("cargo build"));
        assert!(ui.has_message("compile error"));
        assert!(ui.has_message("retry"));
    }

    #[test]
    fn prompt_telemetry_shows_exit_code_when_present() {
        let report = build_report(
            "test",
            "failing cmd",
            Some(42),
            "some error",
            "retry",
            &HashMap::new(),
        );
        let mut ui = crate::ui::MockUI::new();
        ui.set_interactive(true);
        ui.set_prompt_response("telemetry_failure", "no_thanks");

        let _ = prompt_telemetry(&mut ui, &report, None).unwrap();
        assert!(ui.has_message("42"));
    }

    #[test]
    fn prompt_telemetry_hides_exit_code_when_none() {
        let report = build_report("test", "echo", None, "", "retry", &HashMap::new());
        let mut ui = crate::ui::MockUI::new();
        ui.set_interactive(true);
        ui.set_prompt_response("telemetry_failure", "no_thanks");

        let _ = prompt_telemetry(&mut ui, &report, None).unwrap();
        let exit_messages: Vec<_> = ui.messages().iter().filter(|m| m.contains("Exit:")).collect();
        assert!(
            exit_messages.is_empty(),
            "Should not show Exit: when code is None"
        );
    }

    #[test]
    fn prompt_telemetry_hides_empty_error() {
        let report = build_report("test", "echo", Some(0), "", "retry", &HashMap::new());
        let mut ui = crate::ui::MockUI::new();
        ui.set_interactive(true);
        ui.set_prompt_response("telemetry_failure", "no_thanks");

        let _ = prompt_telemetry(&mut ui, &report, None).unwrap();
        let error_msgs: Vec<_> = ui
            .messages()
            .iter()
            .filter(|m| m.contains("Error:"))
            .collect();
        assert!(
            error_msgs.is_empty(),
            "Should not show Error: when empty"
        );
    }

    #[test]
    fn prompt_telemetry_unknown_preference_shows_prompt() {
        let report = build_report("test", "echo", Some(0), "", "retry", &HashMap::new());
        let mut ui = crate::ui::MockUI::new();
        ui.set_interactive(true);
        ui.set_prompt_response("telemetry_failure", "send");

        let result = prompt_telemetry(&mut ui, &report, Some("garbage")).unwrap();
        assert_eq!(result, TelemetryConsent::Send);
        assert!(!ui.prompts_shown().is_empty());
    }

    #[test]
    fn telemetry_prompt_returns_always_from_user() {
        let report = build_report("test", "echo", Some(0), "", "retry", &HashMap::new());
        let mut ui = crate::ui::MockUI::new();
        ui.set_interactive(true);
        ui.set_prompt_response("telemetry_failure", "always");

        let result = prompt_telemetry(&mut ui, &report, None).unwrap();
        assert_eq!(result, TelemetryConsent::Always);
    }

    #[test]
    fn telemetry_prompt_returns_never_from_user() {
        let report = build_report("test", "echo", Some(0), "", "retry", &HashMap::new());
        let mut ui = crate::ui::MockUI::new();
        ui.set_interactive(true);
        ui.set_prompt_response("telemetry_failure", "never");

        let result = prompt_telemetry(&mut ui, &report, None).unwrap();
        assert_eq!(result, TelemetryConsent::Never);
    }

    #[test]
    fn telemetry_prompt_defaults_to_no_thanks() {
        let report = build_report("test", "echo", Some(0), "", "retry", &HashMap::new());
        let mut ui = crate::ui::MockUI::new();
        ui.set_interactive(true);
        // Don't set a response — will fall back to prompt default "no_thanks"

        let result = prompt_telemetry(&mut ui, &report, None).unwrap();
        assert_eq!(result, TelemetryConsent::NoThanks);
    }
}

