/// Save a failure report to a specific directory (for testing).
pub fn save_report_to(report: &FailureReport, dir: &Path) -> Result<PathBuf> {
    std::fs::create_dir_all(dir)?;

    let timestamp = chrono::Utc::now().format("%Y%m%d-%H%M%S");
